package net.civeira.phylax.feature.access.dcrinitialaccesstoken.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class UsesVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property uses of dcr initial access token ")
  void test_uses_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> UsesVO.tryFrom(null));
    Assertions.assertEquals(1, UsesVO.from(1).getUses());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> UsesVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + 1 + "]", UsesVO.from(1).toString());
  }
}
